public static void main(String[] args) {
    Scanner sc = new Scanner(System.in);

    String S = sc.next();
    int sLength = S.length();
    char firstChar = S.charAt(0);
    int uniqueIndex = 0;

    for (int i = 1; i < sLength; i++) {
